entries.syntax_block:
// role module
Procedure OnAccessRead(Source, Operation, Allowed)
{
    Source = Source.Where(Function(x) { Return x.Code = "13"; });
    Allowed = True;
}

entries.syntax_block_ves:
// role module
Procedure OnAccessRead(Source, Operation, Allowed)
    Source = Source.Where(Function(x) Return x.Code = "13"; EndFunction);
    Allowed = True;
EndProcedure

entries.example:
// filter by the current user through an access register
Procedure OnAccessRead(Source, Operation, Allowed)
{
    if (Source = "Catalog.Product") {
        Source = restrict s in Source
                     join a in Data.Registers.WarehouseAccess.Where(Function(a) { Return a.User = CurrentUser(); })
                         on s.Warehouse = a.Warehouse;
    }
    Allowed = True;
}

