// dot-walk works: the platform auto-joins the reference path
Procedure OnAccessRead(Source, Operation, Allowed)
{
    if (Source = "Document.Receipt") {
        Source = Source.Where(Function(x) { Return x.Contract.Company = CurrentCompany(); });
    }
    Allowed = True;
