entries.syntax_block:
Procedure OnAccessWrite(Source, Operation, Allowed)
{
    if (Source = "Catalog.Product") {
        if (Operation = "Delete") {
            Allowed = False;
            Return;
        }
        Source = Source.Where(Function(x) { Return x.Warehouse = CurrentWarehouse(); });
    }
    Allowed = True;
}

